def leader_commit_index(match_index, current_term, log, n_nodes):
    majority = n_nodes // 2 + 1
    for idx in range(len(log) - 1, -1, -1):
        replicas = 1 + sum(1 for m in match_index if m >= idx)
        if replicas >= majority and log[idx].term == current_term:
            return idx
    return -1

import random

def backoff_delay(attempt, base=0.1, cap=30.0):
    ceiling = min(cap, base * (2 ** attempt))
    return random.uniform(0, ceiling)  # full jitter

def should_retry(recent_retries, recent_requests, budget=0.10):
    return recent_retries < budget * recent_requests
